   "hitokoto": "肩書きがいくつもある人の、自己紹介の冒頭に。世界のお手本の棚にある、4本の発表動画を4分割で同時に流すリールに寄せて作った、おけもん版の15秒。黄色いカーソルが十字に伸びて画面を4つの窓に分け、窓ごとに画面が拍で切り替わりながら、「介護福祉士」「Gallup認定ストレングスコーチ」「オフ会主催」「AIと融合中」を同時に1字ずつ打つ。最後は4本のカーソルが1本に戻り、「おけもん」と打つとカピバラが顔を出す。",
