   "aspect": "16:9",
   "hitokoto": "活動の想いを、語りつきの短い映像で届けたい時に。世界のお手本の棚にある、AIの映画づくりの道具で作った短編に寄せて作った、おけもん版の35秒。暗闇で灯りかけては消える小さな光が、神経・枯れ枝・川・花火・万華鏡・銀河と、似た形をたどって広がっていく。語りは、おけもん本人の言葉7つを、AIの声で。曲はおけもんの自作の瞑想の曲（健康編）。",
