   "hitokoto": "一緒に活動する仲間やゲストの紹介に。世界のお手本の棚にある、tldraw の Flash の発表映像（ホワイトボードに手描きの文字が1字ずつ飛んでくる）に寄せて作った、おけもん版の15秒。1本の線がホワイトボードになり、みずやんさんの名前、好きなもの（サウナ・キャンプ・たまごサンド・くんせい）、おけもんと一緒に開いている「ゆるっと水曜AIラジオ」「AI初心者チャット」が1字ずつ集まって、最後にみずやんさん自身の言葉「年中夢中でやってます」だけが差し色で斜めに書かれる。曲はおけもんがみずやんさんのために Suno で作った曲。字の書き順は KanjiVG（CC BY-SA 3.0）。",
