   "hitokoto": "おけちゃんの「私のビジネス風紹介動画も30秒ぐらいで作ってもいいね」「TTSかGeminiのTTSを使って、ちゃんとしたナレーションを」から作った30秒。紺の机の上のプロフィールシートを、カメラが1枚のまま進み、語りに合わせて空欄が埋まっていく：「わたしなんて…」を、日本からなくしたい → ストレングスファインダー認定コーチとして、じぶん探しの楽しさと強みを見つけることを伝える → 1000人以上・イベント100回以上・スキルマーケットのいいね数全体1位 → 夢は、みんなが自由に夢を語れるカフェのような場所をつくること。最後にカピバラのアイコンと「おけもん」。言葉はぜんぶ本人のプロフィールから。ナレーションは Gemini の TTS（無料の枠）、曲はおけもんの自作曲「Afterglow」。数字の回り方は棚の「ヨジノボ6周年」から引き継いだ。カピバラの絵：あや＠ロロカデザインさん。",
