   "hitokoto": "おけちゃんの「名言が流れるやつもやりたいーー」「疲れた時とかのシチュエーション別や」から作った、名言シリーズの1本目・縦長39秒。午後の光が差す紙の壁に、4つの言葉が縦書きで1字ずつ流れては消え、言葉ごとに壁の影が応える（花が咲く・風がやむ・雲が通る・湯気がのぼる）。石川啄木『一握の砂』、セネカ『心の平静について』（ラテン語からうちで訳した）、山村暮鳥『雲』（1925年の初版の字）、岡倉天心『茶の本』（1906年の英文からうちで訳した）。言葉はどれも原典までたどり、肖像は著作権の切れた物だけ。光が夕方の色になって「今日は、ここまでで十分。」。曲はおけもんの自作の瞑想の曲（健康編）。",
