   "hitokoto": "おけちゃんの「ニーチェ、、アドラーとか作り手別とか」「めいげんすきなのーー」から作った、名言シリーズの2本目・縦長40秒。一つの山を夜から夜明けまで登る：混沌の粒から生まれた「踊る星」だけが画面で唯一の色で、嵐を抜け、雲が切れて空が白み、曲の山場で太陽になって空を黄色に染める。言葉は『ツァラトゥストラはこう言った』（1883・1884）、『偶像の黄昏』（1889）、『悦ばしき知識』「上へ」（1882）から4つ。どれもドイツ語の原文を全集で確かめ、うちで訳した。肖像は著作権の切れた1882年の写真。曲はおけもんの自作曲「Night Drive」。",
