   "hitokoto": "アプリの紹介で、ボタンを押す気持ちよさを見せたい時に。世界のお手本の棚にある「押すと気持ちいいボタン集」に寄せて作った、おけもん版の15秒（正方形）。架空のパン屋さんの予約アプリ「こねこね」で、人数・受け取り日・焼き加減・たのしみ度の星・お気に入りのハートを押すたびに、押した点から次の色が丸く広がり、部品の形がそのまま次の部品に変わる。最後は4つのボタンが1点に集まり、最初の黄色い画面に戻ってループ。曲はしゃろうさん「Morning」に「ポッ」「カチッ」の効果音を重ねた。",
