   "hitokoto": "Lottielab の発表映像に寄せて作った、おけもん版の15.7秒（横長）。白地に虹の6色のしまだけが色。真ん中のカードに「えのぐ」「クレヨン」「ねんど」と打たれるたび、虹の額縁が脈打ち、額縁の形も横長・縦長の画用紙2枚・丸いねんど板と材料ごとに変わって作例が拍で入れ替わる。最後は6つのしずくが筆洗いのバケツにたまり、教室の名前と「生徒募集中｜体験会 10月11日（日）」。教室は架空です。曲は「Carefree」Kevin MacLeod (incompetech.com) Licensed under Creative Commons: By Attribution 4.0 License http://creativecommons.org/licenses/by/4.0/ 。",
