   "hitokoto": "架空の「くりのみ通り商店街」の秋のフリーマーケット、出店者さん募集の告知・横長24秒。方眼の地に「いらなくなった」と品物の名前が1語ずつ置かれ、ラジカセ・古本・マグカップ・植木鉢が1つずつ「コトッ」と並ぶ。マスが秋の色で埋まって「それは」「だれかの」「たからもの」とつながり、最後は区画に品物が並んだ会場図に「あなたの区画 空いてます」。お手本は ElevenLabs「Reception」の、方眼と1語ずつの置き方・モザイクの切り替え。商店街・日時・締め切りは架空です。",
