   "hitokoto": "手帳のような方眼の紙の上で、ボール1個だけを使って、動きが気持ちよく見える4つのコツを見せる横長30秒の解説。①着地でつぶれる（スクワッシュ）②跳ぶ前にぐっとためる（アンティシペーション）③等速ではなく、ゆっくり止まる（イーズ）④止まっても、しっぽは遅れてついてくる（フォロースルー）。どれも比べて見せるので、はじめての人でも違いがわかる。最後に4つがまとめて並ぶ。AIに「ためてから跳ねて」「ゆっくり止めて」と頼む時の言葉の見本にも。曲はおけもんの EDM「Afterglow」。",
